import{_ as o,o as t,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Dual-Line Subscription Catalog (Personal Studio & Business Agency Plans) & Admin Plan Editor","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/02-agency-studio-plans/studio-and-agency-plan-catalog/spec.md","filePath":"feature/modules/02-agency-studio-plans/studio-and-agency-plan-catalog/spec.md"}'),i={name:"feature/modules/02-agency-studio-plans/studio-and-agency-plan-catalog/spec.md"};function c(s,e,d,l,r,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="dual-line-subscription-catalog-personal-studio-business-agency-plans-admin-plan-editor" tabindex="-1">Dual-Line Subscription Catalog (Personal Studio &amp; Business Agency Plans) &amp; Admin Plan Editor <a class="header-anchor" href="#dual-line-subscription-catalog-personal-studio-business-agency-plans-admin-plan-editor" aria-label="Permalink to &quot;Dual-Line Subscription Catalog (Personal Studio &amp; Business Agency Plans) &amp; Admin Plan Editor&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>studio-and-agency-plan-catalog</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>02-agency-studio-plans</code> — Agency, Personal Studio, Dashboards &amp; Realtime Notifications</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>studio-personal-plans</code>, <code>personal-workspace-mode</code>, <code>personal-agency-transition</code>, <code>agency-subscription</code>, <code>agency-plus-renewal</code>, <code>agency-plus-style</code>, <code>subscription-four-plan-catalog</code>, <code>subscription-catalog-api-ui</code>, <code>admin-plan-editor</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/08-subscription-billing/3-9-1-upgrade-plan/spec.html">FR 3.9.1 — Upgrade Plan</a> · <a href="./../../../srs/03-agency-workspace/README.html">FR 3.4.1–3.4.5 Agency &amp; Workspace</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Define and govern BrandHub&#39;s complete database-backed <strong>2-Product-Line × 6-Plan Subscription Catalog</strong> with <code>1 / 3 / 6 / 12-month</code> billing cycles, Personal Studio solo-creator mode (<code>company_type = PERSONAL</code>, single-user invariant, seamless <code>PERSONAL -&gt; AGENCY</code> transition), Agency Plus renewal &amp; visual badge styling, and the live <strong>Admin Plan Editor</strong> (<code>/admin?view=plans</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a solo creator <code>Owner</code>, I want a streamlined <strong>Personal Studio</strong> experience (<code>STUDIO_FREE</code>, <code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code>) without multi-member bureaucracy, with the ability to transition my organization to a full <strong>Business Agency</strong> (<code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code>) as my team grows.</li><li>As an <code>Admin</code>, I want to edit plan entitlements, multi-cycle VND prices (<code>1/3/6/12</code> months), and promotional sales on <code>/admin?view=plans</code> with full version history (<code>billing_plan_change_log</code>).</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>2-Product-Line × 6-Plan Matrix (<code>studio-personal-plans</code>, <code>subscription-four-plan-catalog</code>, <code>subscription-catalog-api-ui</code>):</strong><ul><li><strong>Personal Studio Line (<code>company_type = PERSONAL</code>, <code>maxMembers = 1</code>, <code>3</code> on <code>STUDIO_PRO</code>):</strong> <code>STUDIO_FREE</code>, <code>STUDIO_PLUS</code>, <code>STUDIO_PRO</code> (tailored solo workspace limits, S3 vault quota, AI credit grants, self-approval workflow <code>POST /tasks/{id}/self-approve</code>, <code>POST /api/v1/workspaces/personal/bootstrap</code>).</li><li><strong>Business Agency Line (<code>company_type = AGENCY</code>):</strong> <code>BASIC</code>, <code>PLUS</code>, <code>ENTERPRISE</code> (multi-workspace, multi-member <code>Owner / Manager / Creator / Client</code> collaboration, full 3-tier approval).</li></ul></li><li><strong>Multi-Cycle Pricing &amp; Renewal (<code>1 / 3 / 6 / 12</code> Months, <code>agency-plus-renewal</code>, <code>agency-plus-style</code>):</strong> <code>billing_plan_cycle_prices</code> stores exact cycle prices per plan; active <code>PLUS</code> / <code>STUDIO_PLUS</code> / <code>STUDIO_PRO</code> subscribers can renew early (extending <code>current_period_end</code> without losing remaining days) and display semantic <code>Plus</code>/<code>Pro</code> tier badges.</li><li><strong>Personal-to-Agency Transition (<code>personal-agency-transition</code>):</strong> A <code>PERSONAL</code> Studio <code>Owner</code> can upgrade/convert <code>company_type</code> from <code>PERSONAL</code> to <code>AGENCY</code>, unlocking multi-member invitations (<code>agency_invitations</code>) and mapping studio entitlements cleanly to the Business Agency catalog without losing Workspaces, Materials, or Posts.</li><li><strong>Admin Plan Editor (<code>/admin?view=plans</code>, <code>admin-plan-editor</code>):</strong> <code>AdminPlanController</code> (<code>GET /api/v1/admin/billing/plans</code>, <code>PUT /{code}</code>, <code>POST /{code}/sale</code>, <code>GET /{code}/history</code>) enables <code>Admin</code> to update display names, limits, <code>1/3/6/12</code>-month cycle prices, and time-bounded promotional sales, appending immutable versions in <code>billing_plan_versions</code> and <code>billing_plan_change_log</code> without mutating already-purchased active subscription snapshots.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>subscription.studio.*</code>, <code>subscription.plans.*</code>, <code>agency.companyType.*</code>, <code>admin.plans.*</code> in <code>src/i18n/locales/{vi,en}/{subscription,agency,admin}.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/agency/components/CompanyTypeChooser.tsx</code>, <code>CompanyPlanSelector.tsx</code>, <code>pages/workspace/components/PersonalQuickLaunchpad.tsx</code>, <code>pages/admin/components/AdminPlansPanel.tsx</code>, <code>AdminPlanEditDialog.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/SubscriptionPlansScreen.tsx</code>, <code>src/components/billing/StudioPlanCard.tsx</code>, <code>SubscriptionPlanCard.tsx</code> (<code>studioPlans.test.ts</code>)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/public/billing/plans &amp; GET /api/v1/billing/plans?agencyId={id}</code></td><td style="text-align:left;">Guest / Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>PublicBillingPlanController</code> &amp; <code>BillingPlanController</code> -&gt; live DB catalog filtered by <code>company_type</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/personal/bootstrap</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>WorkspaceController</code> -&gt; idempotently bootstraps Solo Studio Workspace for <code>PERSONAL</code> mode</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/admin/billing/plans &amp; PUT /{code} &amp; POST /{code}/sale &amp; GET /{code}/history</code></td><td style="text-align:left;">Bearer (<code>Admin</code>)</td><td style="text-align:left;"><code>AdminPlanController</code> -&gt; live catalog editing, promotional sale scheduling &amp; <code>billing_plan_change_log</code> audit</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Member Cap on <code>PERSONAL</code> Studio (<code>2026-11-22-studio-single-user.sql</code>, <code>2026-11-24-studio-pro-members.sql</code>):</strong> <code>STUDIO_FREE</code> and <code>STUDIO_PLUS</code> are one user; <code>STUDIO_PRO</code> allows 3 internal members (owner + 2). Clients are never allowed in a <code>PERSONAL</code> company (<code>maxClients = 0</code>). Inviting beyond the cap rejects with <code>403/409</code> instructing transition to <code>AGENCY</code> mode first.</li><li><strong>Active Subscriber Isolation on Admin Price Edit:</strong> Editing a plan&#39;s price on <code>/admin?view=plans</code> affects new orders/renewals only; active <code>agency_subscription_periods</code> retain their contracted price and entitlements until period end.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/08-subscription-billing/3-9-1-upgrade-plan/spec.html">FR 3.9.1 — Upgrade Plan</a> · <a href="./../../../srs/03-agency-workspace/README.html">FR 3.4.1–3.4.5 Agency &amp; Workspace</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/03-agency-workspace.html">BA 03 Agency &amp; Workspace</a> · <a href="./../../../../ba/08-subscription-billing.html">BA 08 Subscription &amp; Billing</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=o(i,[["render",c]]);export{u as __pageData,m as default};
